@extends('layout') @section('content')<div class="section-heading"><a href="{{ route('dashboard') }}">← Redaktion</a><h1>{{ $organization->exists ? $organization->name : 'Eine neue Stimme.' }}</h1></div><div class="dashboard-grid"><section class="panel"><h2>Organisationsprofil</h2>@if(!$organization->exists || auth()->user()->can('update', $organization))<form method="post" enctype="multipart/form-data" action="{{ $organization->exists ? route('organizations.update', $organization) : route('organizations.store') }}" class="form">@csrf @if($organization->exists) @method('PUT') @endif<label>Name<input name="name" required maxlength="120" value="{{ old('name', $organization->name) }}"></label><label>Adresse / Kurzname<input name="slug" required maxlength="100" pattern="[a-z0-9]+(-[a-z0-9]+)*" placeholder="z. B. sv-musterstadt" value="{{ old('slug', $organization->slug) }}"><small>Kleinbuchstaben, Zahlen und Bindestriche</small></label><label>Organisationstyp<select name="type">@foreach(['club'=>'Verein', 'business'=>'Geschäft', 'city'=>'Stadt / Amt', 'other'=>'Sonstige'] as $value=>$label)<option value="{{ $value }}" @selected(old('type', $organization->type) === $value)>{{ $label }}</option>@endforeach</select></label><label>Beschreibung<textarea name="description" rows="4" maxlength="1000">{{ old('description', $organization->description) }}</textarea></label>@if($organization->exists)<label>Logo (JPG, PNG, WebP; max. 2 MB)<input type="file" name="logo" accept="image/jpeg,image/png,image/webp"></label>@endif<button class="button" type="submit">Profil speichern ↗</button></form>@else<p>Du kannst hier das Team sehen. Profileinstellungen bearbeiten Owner und Admins.</p>@endif</section>@if($organization->exists)<aside class="panel"><h2>Euer Team</h2>@foreach($organization->users as $member)<div class="member-row"><div><strong>{{ $member->name }}</strong><small>{{ $member->pivot->role }}</small></div>@can('manageMembers', $organization)@if($member->pivot->role !== 'owner'